parent = []
rank = []

def findRoot(node):
	global parent
	while parent[node] != node:
		parent[node] = parent[parent[node]]
		node = parent[node]
	return node

def unionRoot(node1, node2):
	global parent, rank
	root1 = findRoot(node1)
	root2 = findRoot(node2)
	if root1 != root2:
		if rank[root1] > rank[root2]:
			parent[root2] = root1
		elif rank[root2] > rank[root1]:
			parent[root1] = root2
		else:
			parent[root1] = root2
			rank[root2] += 1
		return True
	else:
		return False

def kruskal(n, edges):
	global parent, rank
	parent = [node for node in range(n)]
	rank = [0] * n
	length = 0
	edges = sorted(edges, key=lambda x: x[0])
	n -= 1
	for (c, u, v) in edges:
		if unionRoot(u, v):
			length += c
			n -= 1
			if n == 0:
				break
	return length

