	t = tree
	num = compressStr(num, numLen)
	while num:
		tv = t['v']
		(same, vleft, num) = diffCompressedStr(tv, num)
		if not vleft:
			if num:
				u = num[0][1]
				ru = rev(u)
				if u in t:
					t['c'].append(idx)
					t = t[u]
					num = popLeft(num, 1)
				elif ru in t:
					t[u] = {'c': [idx], 'v': popLeft(num, 1)}
				else:
					t['c'].append(idx)
					t['v'] = num
					return
			else:
				t['c'].append(idx)
				return
		else:
			c0 = t['0'] if '0' in t else None
			c1 = t['1'] if '1' in t else None
			v0 = vleft[0][1]
			n0 = num[0][1]
			t[n0] = {'c': [idx], 'v': popLeft(num, 1)}
			t[v0] = {'c': [x for x in t['c']], 'v': popLeft(vleft, 1)}
			if c0:
				t[v0]['0'] = c0
			if c1:
				t[v0]['1'] = c1
			t['v'] = same
			t['c'].append(idx)
			return
	t['c'].append(idx)

