def check(l, r, idx):
	if not idx:
		return False
	if idx[0] > r or idx[-1] < l:
		return False
	if l <= idx[0] <= idx[-1] <= r:
		return True
	(a, b) = (0, len(idx))
	while a < b:
		c = (a + b) // 2
		v = idx[c]
		if l <= v <= r:
			return True
		if v < l:
			a = c + 1
		elif v > r:
			b = c
	return False

def find(l, r, idx):
	(a, b) = (0, len(idx))
	while a < b:
		c = (a + b) // 2
		v = idx[c]
		if v < l:
			a = c + 1
		elif v > r:
			b = c
		else:
			b = c
	return idx[a]

def query(l, r, num):
