		a = num[0][1]
		ra = rev(a)
		if ra in t and check(l, r, t[ra]['c']):
			t = t[ra]
			num = popLeft(num, 1)
		elif a in t and check(l, r, t[a]['c']):
			t = t[a]
			num = popLeft(num, 1)
		else:
			break
	return find(l, r, t['c'])
