from enum import Enum, auto

class RedBlackTree:

	class Colour(Enum):
		RED = auto()
		BLACK = auto()

	class Node:

		def __init__(self, key):
			self.parent = None
			self.left = None
			self.right = None
			self.colour = RedBlackTree.Colour.RED
			self.key = key

		@property
		def grandparent(self):
			return self.parent and self.parent.parent

		@property
		def sibling(self):
			p = self.parent
			return p and (p.right if p.left == self else p.left)

		@property
		def uncle(self):
			p = self.parent
			return p and p.sibling

		def has_red_child(self):
			return self.left and self.left.colour == RedBlackTree.Colour.RED or (self.right and self.right.colour == RedBlackTree.Colour.RED)

		def is_on_left(self):
			return self.parent.left == self

		def find(self, v):
			if self.key == v:
				return self
			child = self.left if self.key > v else self.right
			return child and child.find(v)

		def far_left(self):
			if self.left:
				return self.left.far_left()
			else:
				return self

		def far_right(self):
			if self.right:
				return self.right.far_right()
			else:
				return self

		def next(self):
			if self.right:
				return self.right.far_left()
			n = self
			p = n.parent
			while p:
				if n == p.left:
					return p
				n = p
				p = n.parent
			return None

		def prev(self):
			if self.left:
				return self.left.far_right()
			n = self
			p = n.parent
			while p:
				if n == p.right:
					return p
				n = p
				p = n.parent
			return None

		def __str__(self):
			return str(self.key) + ' ' + str(self.colour)

	def __init__(self):
		self.root = None
		self.len = 0

	@staticmethod
	def is_red(node):
		return node and node.colour == RedBlackTree.Colour.RED

	def rotate_left(self, n):
		nnew = n.right
		p = n.parent
		n.right = nnew.left
		nnew.left = n
		n.parent = nnew
		if n.right:
			n.right.parent = n
		if p:
			if n == p.left:
				p.left = nnew
			elif n == p.right:
				p.right = nnew
		else:
			self.root = nnew
		nnew.parent = p

	def rotate_right(self, n):
		nnew = n.left
		p = n.parent
		n.left = nnew.right
		nnew.right = n
		n.parent = nnew
		if n.left:
			n.left.parent = n
		if p:
			if n == p.left:
				p.left = nnew
			elif n == p.right:
				p.right = nnew
		else:
			self.root = nnew
		nnew.parent = p

	def insert(self, k):
		n = self.Node(k)

		def insert_recurse(root):
			if root and n.key < root.key:
				if root.left:
					insert_recurse(root.left)
					return
				else:
					root.left = n
			elif root:
				if root.right:
					insert_recurse(root.right)
					return
				else:
					root.right = n
			n.parent = root

		def repair_insert(n):
			if not n.parent:
				n.colour = RedBlackTree.Colour.BLACK
			elif n.parent.colour == RedBlackTree.Colour.BLACK:
				return
			elif n.uncle and n.uncle.colour == RedBlackTree.Colour.RED:
				n.parent.colour = RedBlackTree.Colour.BLACK
				n.uncle.colour = RedBlackTree.Colour.BLACK
				n.grandparent.colour = RedBlackTree.Colour.RED
				repair_insert(n.grandparent)
			else:
				p = n.parent
				g = n.grandparent
				if n == p.right and p == g.left:
					self.rotate_left(p)
					n = n.left
				elif n == p.left and p == g.right:
					self.rotate_right(p)
					n = n.right
				p = n.parent
				g = n.grandparent
				if n == p.left:
					self.rotate_right(g)
				else:
					self.rotate_left(g)
				p.colour = RedBlackTree.Colour.BLACK
				g.colour = RedBlackTree.Colour.RED
		insert_recurse(self.root)
		repair_insert(n)
		self.root = n
		while self.root.parent:
			self.root = self.root.parent
		self.len += 1

	def remove(self, v):

		def fix_double_black(n):
			if n == self.root:
				return
			p = n.parent
			s = n.sibling
			if not s:
				fix_double_black(n.parent)
				return
			if s.colour == RedBlackTree.Colour.RED:
				p.colour = RedBlackTree.Colour.RED
				s.colour = RedBlackTree.Colour.BLACK
				if p.left == n:
					self.rotate_left(p)
				else:
					self.rotate_right(p)
				fix_double_black(n)
			elif s.has_red_child():
				if self.is_red(s.left):
					if s.is_on_left():
						s.left.colour = s.colour
						s.colour = p.colour
						self.rotate_right(p)
					else:
						s.left.colour = p.colour
						self.rotate_right(s)
						self.rotate_left(p)
				elif s.is_on_left():
					s.right.colour = p.colour
					self.rotate_left(s)
					self.rotate_right(p)
				else:
					s.right.colour = s.colour
					s.colour = p.colour
					self.rotate_left(p)
				p.colour = RedBlackTree.Colour.BLACK
			else:
				s.colour = RedBlackTree.Colour.RED
				if p.colour == RedBlackTree.Colour.BLACK:
					fix_double_black(p)
				else:
					p.colour = RedBlackTree.Colour.BLACK

		def delete(n):
			child = n.left or n.right
			if not (self.is_red(n) or self.is_red(child)):
				fix_double_black(n)
			if child:
				child.parent = n.parent
				child.colour = RedBlackTree.Colour.BLACK
			if not n.parent:
				self.root = child
			elif n.is_on_left():
				n.parent.left = child
			else:
				n.parent.right = child
		n = self.root.find(v)
		if n.right and n.left:
			m = n.right.far_left()
			n.key = m.key
			n = m
		delete(n)
		self.len -= 1

	def find(self, v):
		return self.root and self.root.find(v)

	def __iter__(self):
		if not self.root:
			return None
		n = self.root.far_left()
		while n:
			yield n.key
			n = n.next()

	def __len__(self):
		return self.len

