class SegmentTree:

	def __init__(self, arr):
		self.size = len(arr)
		self.tree = [0] * (2 * self.size)
		self.build(arr)

	def build(self, arr):
		for i in range(n):
			self.tree[i + n] = arr[i]
		for i in range(self.size - 1, 0, -1):
			self.tree[i] = self.tree[i << 1] + self.tree[i << 1 | 1]

	def query(self, l, r):
		if l > r:
			return 0
		l += self.size
		r += self.size
		s = 0
		while l <= r:
			if l % 2 == 1:
				s += self.tree[l]
				l += 1
			if r % 2 == 0:
				s += self.tree[r]
				r -= 1
			l >>= 1
			r >>= 1
		return s

	def update(self, i, x):
		i += n
		self.tree[i] = x
		while i > 1:
			self.tree[i >> 1] = self.tree[i] + self.tree[i ^ 1]
			i >>= 1

