	def check(self, T, S):
		if S == None and T == None:
			return 1
		if T != None and S == None or (T == None and S != None):
			return 0
		l = self.check(T.left, S.left)
		r = self.check(T.right, S.right)
		if T.data == S.data and l == 1 and (r == 1):
			return 1
		else:
			return 0

	def isSubTree(self, T, S):
		q = [T]
		while len(q) > 0:
			temp = q[0]
			q.pop(0)
			if temp.data == S.data:
				if self.check(temp, S) == 1:
					return True
			if temp.left != None:
				q.append(temp.left)
			if temp.right != None:
				q.append(temp.right)
		return False

