import math

def solve(n, x, y, a):
	a.sort()
	for i in range(n):
		a[i] -= i
	res = 0
	for (idx, el) in enumerate(a):
		if x >= el:
			continue
		if y - x <= idx:
			return res + (y - x)
		dx = 2 * idx - n
		if dx <= 0:
			if y - x > idx:
				return -1
			return y - x
		if el >= y - idx:
			iters = math.ceil((y - x - idx) / dx)
			res += iters * n
			x += iters * dx
			break
		else:
			iters = math.ceil((el - x) / dx)
			res += iters * n
			x += iters * dx
	return res + (y - x)

