		for dest in adj[end1]:
			if dest != par:
				dq.append((dest, end1))
	prev = [-1] * n
	prev[end1] = -2
	dq = deque([(end1, 0)])
	while dq:
		(end2, diameter) = dq.popleft()
		for dest in adj[end2]:
			if prev[dest] == -1:
				prev[dest] = end2
				dq.append((dest, diameter + 1))
	return (end1, end2, diameter, prev)
