	return pow(a, b - 2, b)
MOD = 998244353

def multiply(A):
	if len(A) == 1:
		return A[0]
	mid = len(A) // 2
	return poly_mul_mod(multiply(A[:mid]), multiply(A[mid:]), MOD)

def sum_of_powers(N, n):
	(A, B) = ([0] * n, [0] * n)
	A[0] = 1
	B[0] = N
	P = (N + 1) % MOD
	for i in range(1, n):
		A[i] = A[i - 1] * inv(i + 1, MOD) % MOD
		P = P * (N + 1) % MOD
		B[i] = (P - 1) * A[i] % MOD
	F = poly_mul_mod(B, poly_inverse_mod(A, n, MOD), MOD)[:n]
	P = 1
	for i in range(1, n):
		P = P * i % MOD
		F[i] = F[i] * P % MOD
	return F
