def factorize(M):
	factors.clear()
	for i in range(0, len(primes)):
		if M == 1:
			break
		if M % primes[i] == 0:
			cnt = 0
			while M % primes[i] == 0:
				cnt = cnt + 1
				M = M / primes[i]
			factors.append(tuple([primes[i], 2 * cnt]))
	if M != 1:
		factors.append(tuple([M, 2]))
	return
ans = []

