(U, L) = ([], [])

def Convex_hull(P):
	global U, L
	(U, L) = ([], [])
	sz = len(P)
	for i in range(sz):
		while len(U) >= 2 and cross(U[-2], U[-1], P[i]) <= 0:
			U.pop()
		while len(L) >= 2 and cross(L[-2], L[-1], P[i]) >= 0:
			L.pop()
		L.append(P[i])
		U.append(P[i])

def Find_maximization_pair():
	global U, L
	ans = 0
	(P, Q) = (0, 0)
	sizeU = len(U)
	sizeL = len(L)
	(i, j) = (0, sizeL - 1)
	while 0 < j or i < sizeU - 1:
		tmpdist = dist(U[i], L[j])
		if tmpdist > ans:
			(P, Q, ans) = (i, j, tmpdist)
