	def numberOfPairs(self, a: List[int], pairs: List[List[int]]) -> int:
		visit = [0] * a[0]
		adj = [[] for _ in range(a[0])]
		for i in pairs:
			adj[i[0]].append(i[1])
			adj[i[1]].append(i[0])

		def fun(u, c):
			visit[u] = 1
			q = deque()
			q.append(u)
			while q:
				t = q.popleft()
				c += 1
				for i in adj[t]:
					if visit[i] == 0:
						visit[i] = 1
						q.append(i)
			return c
		ans = 0
		for i in range(a[0]):
			if visit[i] == 0:
				c = fun(i, 0)
				ans += c * (a[0] - c)
		return ans // 2

