def find_factorial_factor(N):
	dic = {}
	for p in P:
		if p > 10 ** 6:
			break
		if p > N:
			break
		temp = p
		count = 0
		while temp <= N:
			count += N // temp
			temp *= p
		dic[p] = count
	return dic

