from collections import deque

def bfs(visit, graph, level, i):
	visit[i] = 1
	q = deque()
	q.append([1, 0])
	while q:
		t = q.popleft()
		u = t[0]
		lev = t[1]
		if lev not in level:
			level[lev] = [u]
		else:
			level[lev].append(u)
		for v in graph[u]:
			if visit[v] == 0:
				visit[v] = 1
				q.append([v, lev + 1])

class Solution:

