def generate_primes(max_number):
	is_prime = [True] * (max_number + 1)
	is_prime[1] = False
	primes = []
	i = 2
	while i * i <= max_number:
		if is_prime[i]:
			primes.append(i)
			j = i * i
			while j <= max_number:
				is_prime[j] = False
				j += i
		i += 1
	return (primes, is_prime)

def get_bucket(n, primes, is_prime):
	bucket = 1
	for prime in primes:
		if n == 1:
			return bucket
		if is_prime[n]:
			bucket *= n
			break
		count = 0
		while n % prime == 0:
			n //= prime
			count += 1
		if count % 2 == 1:
			bucket *= prime
	return bucket
