from itertools import accumulate

class Solution:

	def solveQueries(self, n, Queries):
		temp = [[0] * n for _ in range(n)]
		for (a, b, c, d) in Queries:
			for i in range(a, c + 1):
				temp[i][b] += 1
			if d < n - 1:
				for i in range(a, c + 1):
					temp[i][d + 1] -= 1
		for i in range(n):
			temp[i] = list(accumulate(temp[i]))
		return temp

class Solution:

	def getHeight(self, root):
		if not root:
			return 0
		return root.height

	def leftrotate(self, root):
		node = root.right
		temp = node.left
		node.left = root
		root.right = temp
		root.height = 1 + max(self.getHeight(root.left), self.getHeight(temp))
		node.height = 1 + max(self.getHeight(root), self.getHeight(node.right))
		return node

	def rightrotate(self, root):
		node = root.left
		temp = node.right
		node.right = root
		root.left = temp
		root.height = 1 + max(self.getHeight(root.right), self.getHeight(temp))
		node.height = 1 + max(self.getHeight(root), self.getHeight(node.left))
		return node

