class Solution:

	def rotate(self, head, k):
		if head == None or k == 0:
			return head
		prev = head
		while prev.next:
			prev = prev.next
		for i in range(k):
			prev.next = head
			head = head.next
			prev = prev.next
			prev.next = None
		return head

