def getHeight(root):
	if root is None:
		return 0
	return root.height

def rightRotate(disbalancedNode):
	newRoot = disbalancedNode.left
	disbalancedNode.left = disbalancedNode.left.right
	newRoot.right = disbalancedNode
	disbalancedNode.height = 1 + max(getHeight(disbalancedNode.left), getHeight(disbalancedNode.right))
	newRoot.height = 1 + max(getHeight(newRoot.left), getHeight(newRoot.right))
	return newRoot

def leftRotate(disbalancedNode):
	newRoot = disbalancedNode.right
	disbalancedNode.right = disbalancedNode.right.left
	newRoot.left = disbalancedNode
	disbalancedNode.height = 1 + max(getHeight(disbalancedNode.left), getHeight(disbalancedNode.right))
	newRoot.height = 1 + max(getHeight(newRoot.left), getHeight(newRoot.right))
	return newRoot

def getBalance(root):
	if root is None:
		return 0
	return getHeight(root.left) - getHeight(root.right)

def getMinValueNode(root):
	if root is None or root.left is None:
		return root
	return getMinValueNode(root.left)

def deleteNode(root, key):
	if root is None:
		return root
	elif key < root.data:
		root.left = deleteNode(root.left, key)
	elif key > root.data:
		root.right = deleteNode(root.right, key)
	else:
		if root.left is None:
			curr = root.right
			root = None
			return curr
		if root.right is None:
			curr = root.left
			root = None
			return curr
		curr = getMinValueNode(root.right)
		root.data = curr.data
		root.right = deleteNode(root.right, curr.data)
	root.height = 1 + max(getHeight(root.left), getHeight(root.right))
	balance = getBalance(root)
	if balance > 1 and getBalance(root.left) >= 0:
		return rightRotate(root)
	elif balance > 1 and getBalance(root.left) < 0:
		root.left = leftRotate(root.left)
		return rightRotate(root)
	elif balance < -1 and getBalance(root.right) <= 0:
		return leftRotate(root)
	elif balance < -1 and getBalance(root.right) > 0:
		root.right = rightRotate(root.right)
		return leftRotate(root)
	return root

class Solution:

	def superEggDrop(self, K: int, N: int) -> int:

		def f(t):
			a = 0
			r = 1
			for i in range(1, K + 1):
				r *= t - i + 1
				r //= i
				a += r
				if a >= N:
					break
			return a
		(l, h) = (1, N)
		while l < h:
			m = (l + h) // 2
			if f(m) < N:
				l = m + 1
			else:
				h = m
		return l

