	def containsCycle(self, grid: List[List[str]]) -> bool:
		n = len(grid)
		m = len(grid[0])
		F = [i for i in range(m * n)]

		def find(x):
			if x == F[x]:
				return x
			else:
				F[x] = find(F[x])
				return F[x]
		for i in range(n):
			for j in range(m):
